79	    async fn run_session(
80	        &self,
81	        device_id: &str,
82	        device_name: &str,
83	        room_id: &str,
84	        key: &[u8; 32],
85	    ) -> Result<()> {
86	        let (ws_stream, _) = connect_async(&self.config.signaler_url).await?;
87	        let (mut ws_sender, mut ws_receiver) = ws_stream.split();
88	
89	        // Register Node
90	        let reg_msg = SignalMessage::RegisterNode {
91	            room: room_id.to_string(),
92	            device_id: device_id.to_string(),
93	            device_name: device_name.to_string(),
94	            os: std::env::consts::OS.to_string(),
95	            capabilities: vec![
96	                "shell".into(),
97	                "fs".into(),
98	                "desktop_gui".into(),
99	                "adb".into(),
100	            ],
101	            screen_width: 1920,
102	            screen_height: 1080,
103	        };
104	
105	        ws_sender
106	            .send(Message::Text(serde_json::to_string(&reg_msg)?.into()))
107	            .await?;
108	        tracing::info!("Node successfully registered in room '{}'", room_id);
109	
110	        let shell_runner = ShellRunner::new(self.interceptor.clone());
111	
112	        while let Some(msg) = ws_receiver.next().await {
113	            let msg = match msg {
114	                Ok(Message::Text(t)) => t,
115	                Ok(Message::Ping(_)) => {
116	                    let _ = ws_sender.send(Message::Pong(vec![].into())).await;
117	                    continue;
118	                }
119	                Ok(Message::Close(_)) => break,
120	                _ => continue,
121	            };
122	
123	            let signal_msg: SignalMessage = match serde_json::from_str(&msg) {
124	                Ok(m) => m,
125	                Err(e) => {
126	                    tracing::warn!("Failed to parse signal message: {}", e);
127	                    continue;
128	                }
129	            };
130	
131	            match signal_msg {
132	                SignalMessage::ToNode {
133	                    target_device_id,
134	                    encrypted_payload,
135	                } => {
136	                    if target_device_id != device_id {
137	                        continue;
138	                    }
139	
140	                    // Decrypt payload
141	                    let plaintext = match decrypt(key, &encrypted_payload) {
142	                        Ok(p) => p,
143	                        Err(e) => {
144	                            tracing::error!("Failed to decrypt message: {}", e);
145	                            continue;
146	                        }
147	                    };
148	
149	                    let req: RpcEnvelope = match serde_json::from_slice(&plaintext) {
150	                        Ok(r) => r,
151	                        Err(e) => {
152	                            tracing::error!("Failed to parse RPC envelope: {}", e);
153	                            continue;
154	                        }
155	                    };
156	
157	                    // Execute RPC
158	                    let (success, result, err_msg) =
159	                        self.handle_rpc(&req, &shell_runner, device_id).await;
160	
161	                    let resp = RpcResponseEnvelope {
162	                        id: req.id,
163	                        success,
164	                        result,
165	                        error: err_msg,
166	                    };
167	
168	                    // Encrypt response and send to hub
169	                    let resp_bytes = serde_json::to_vec(&resp)?;
170	                    let encrypted_resp = encrypt(key, &resp_bytes)?;
171	
172	                    let to_hub = SignalMessage::ToHub {
173	                        from_device_id: device_id.to_string(),
174	                        encrypted_payload: encrypted_resp,
175	                    };
176	
177	                    ws_sender
178	                        .send(Message::Text(serde_json::to_string(&to_hub)?.into()))
179	                        .await?;
180	                }
181	                _ => {}
182	            }
183	        }
184	
185	        Ok(())
186	    }
