1	use crate::protocol::{
2	    FileEntry, FileListParams, FileListResult, FileReadParams, FileReadResult, FileWriteParams,
3	    FileWriteResult,
4	};
5	use anyhow::{anyhow, Result};
6	use base64::{engine::general_purpose::STANDARD as B64, Engine as _};
7	use std::fs;
8	use std::path::Path;
9	use std::time::UNIX_EPOCH;
10	
11	pub struct FsRunner;
12	
13	impl FsRunner {
14	    pub fn read_file(params: FileReadParams) -> Result<FileReadResult> {
15	        let path = Path::new(&params.path);
16	        if !path.exists() {
17	            return Err(anyhow!("File does not exist: {}", params.path));
18	        }
19	
20	        let bytes = fs::read(path).map_err(|e| anyhow!("Failed to read file: {}", e))?;
21	        let size = bytes.len() as u64;
22	
23	        let is_binary = params.binary.unwrap_or_else(|| {
24	            // Heuristic: check for null bytes in the first 1KB
25	            bytes.iter().take(1024).any(|&b| b == 0)
26	        });
27	
28	        let content = if is_binary {
29	            B64.encode(&bytes)
30	        } else {
31	            String::from_utf8(bytes).map_err(|_| anyhow!("File contains invalid UTF-8 bytes"))?
32	        };
33	
34	        Ok(FileReadResult {
35	            content,
36	            is_binary,
37	            size,
38	        })
39	    }
40	
41	    pub fn write_file(params: FileWriteParams) -> Result<FileWriteResult> {
42	        let path = Path::new(&params.path);
43	        if let Some(parent) = path.parent() {
44	            fs::create_dir_all(parent)
45	                .map_err(|e| anyhow!("Failed to create parent directories: {}", e))?;
46	        }
47	
48	        let bytes = if params.binary.unwrap_or(false) {
49	            B64.decode(&params.content)
50	                .map_err(|e| anyhow!("Invalid base64 binary content: {}", e))?
51	        } else {
52	            params.content.into_bytes()
53	        };
54	
55	        let bytes_written = bytes.len() as u64;
56	        fs::write(path, bytes).map_err(|e| anyhow!("Failed to write file: {}", e))?;
57	
58	        Ok(FileWriteResult { bytes_written })
59	    }
60	
61	    pub fn list_dir(params: FileListParams) -> Result<FileListResult> {
62	        let path = Path::new(&params.path);
63	        if !path.exists() {
64	            return Err(anyhow!("Directory does not exist: {}", params.path));
65	        }
66	
67	        let read_dir = fs::read_dir(path).map_err(|e| anyhow!("Failed to read directory: {}", e))?;
68	        let mut entries = Vec::new();
69	
70	        for entry in read_dir.flatten() {
71	            let metadata = entry.metadata().ok();
72	            let is_dir = metadata.as_ref().map(|m| m.is_dir()).unwrap_or(false);
73	            let size = metadata.as_ref().map(|m| m.len()).unwrap_or(0);
74	            let modified_secs = metadata
75	                .and_then(|m| m.modified().ok())
76	                .and_then(|t| t.duration_since(UNIX_EPOCH).ok())
77	                .map(|d| d.as_secs());
78	
79	            entries.push(FileEntry {
80	                name: entry.file_name().to_string_lossy().to_string(),
81	                path: entry.path().to_string_lossy().to_string(),
82	                is_dir,
83	                size,
84	                modified_secs,
85	            });
86	        }
87	
88	        entries.sort_by(|a, b| b.is_dir.cmp(&a.is_dir).then_with(|| a.name.cmp(&b.name)));
89	
90	        Ok(FileListResult { entries })
91	    }
92	}

