17	        if let Err(e) = self.interceptor.check_command(&params.command) {
18	            return Err(anyhow!("Security policy violation: {}", e));
19	        }
20	
21	        let start = Instant::now();
22	        let timeout_secs = params.timeout_secs.unwrap_or(60);
23	
24	        #[cfg(target_os = "windows")]
25	        let mut cmd = {
26	            let mut c = tokio::process::Command::new("powershell.exe");
27	            c.arg("-Command").arg(&params.command);
28	            c
29	        };
30	
31	        #[cfg(not(target_os = "windows"))]
32	        let mut cmd = {
33	            let shell = std::env::var("SHELL").unwrap_or_else(|_| "/bin/sh".into());
34	            let mut c = tokio::process::Command::new(shell);
35	            c.arg("-c").arg(&params.command);
36	            c
37	        };
38	
39	        if let Some(ref cwd) = params.cwd {
40	            cmd.current_dir(cwd);
41	        }
42	
43	        cmd.stdout(std::process::Stdio::piped());
44	        cmd.stderr(std::process::Stdio::piped());
45	
46	        let child = cmd.spawn().map_err(|e| anyhow!("Failed to spawn process: {}", e))?;
47	
48	        let output = tokio::time::timeout(
49	            Duration::from_secs(timeout_secs),
50	            child.wait_with_output(),
51	        )
52	        .await
53	        .map_err(|_| anyhow!("Command timed out after {} seconds", timeout_secs))?
54	        .map_err(|e| anyhow!("Failed to wait for process: {}", e))?;
55	
56	        let duration_ms = start.elapsed().as_millis() as u64;
57	
58	        let stdout = String::from_utf8_lossy(&output.stdout).to_string();
59	        let stderr = String::from_utf8_lossy(&output.stderr).to_string();
60	        let exit_code = output.status.code().unwrap_or(-1);
61	
62	        Ok(ExecCommandResult {
63	            stdout,
64	            stderr,
65	            exit_code,
