43	    pub async fn run_stdio(&self) -> Result<()> {
44	        let stdin = tokio::io::stdin();
45	        let mut reader = BufReader::new(stdin).lines();
46	        let mut stdout = tokio::io::stdout();
47	
48	        while let Some(line) = reader.next_line().await? {
49	            let line = line.trim();
50	            if line.is_empty() {
51	                continue;
52	            }
53	
54	            let req: JsonRpcRequest = match serde_json::from_str(line) {
55	                Ok(r) => r,
56	                Err(e) => {
57	                    let err_resp = JsonRpcResponse {
58	                        jsonrpc: "2.0".into(),
59	                        id: None,
60	                        result: None,
61	                        error: Some(JsonRpcError {
62	                            code: -32700,
63	                            message: format!("Parse error: {}", e),
64	                            data: None,
65	                        }),
66	                    };
67	                    let line_out = serde_json::to_string(&err_resp)? + "\n";
68	                    stdout.write_all(line_out.as_bytes()).await?;
69	                    stdout.flush().await?;
70	                    continue;
71	                }
72	            };
73	
74	            // Process request
75	            let resp = self.handle_request(req).await;
76	            if let Some(r) = resp {
77	                let line_out = serde_json::to_string(&r)? + "\n";
78	                stdout.write_all(line_out.as_bytes()).await?;
79	                stdout.flush().await?;
80	            }
81	        }
82	
83	        Ok(())
84	    }
