/**
 * dsh-context-distill — storage persistence layer.
 *
 * Persists session distillation metrics, history, and global aggregates
 * in ~/.dsh/storages/context-distill/ using atomic file operations.
 *
 * @module dsh-context-distill/storage
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync, renameSync, readdirSync } from 'node:fs';
import { homedir } from 'node:os';
import { join, resolve } from 'node:path';

function getStorageRoot() {
  if (process.env.DSH_OSWYN_STORAGE_DIR) {
    const dir = resolve(process.env.DSH_OSWYN_STORAGE_DIR);
    const sessionsDir = join(dir, 'sessions');
    if (!existsSync(sessionsDir)) {
      mkdirSync(sessionsDir, { recursive: true, mode: 0o700 });
    }
    return dir;
  }
  const base = process.env.DSH_HOME ? resolve(process.env.DSH_HOME) : join(homedir(), '.dsh');
  const dir = join(base, 'storages', 'oswyn');
  const oldDir = join(base, 'storages', 'context-distill');
  if (!existsSync(dir) && existsSync(oldDir)) {
    try {
      renameSync(oldDir, dir);
    } catch (_) {}
  }
  const sessionsDir = join(dir, 'sessions');
  if (!existsSync(sessionsDir)) {
    mkdirSync(sessionsDir, { recursive: true, mode: 0o700 });
  }
  return dir;
}

function getSessionsDir() {
  const root = getStorageRoot();
  return join(root, 'sessions');
}

function sessionPath(sessionId) {
  const safeId = String(sessionId).replace(/[^a-zA-Z0-9_-]/g, '_');
  return join(getSessionsDir(), `${safeId}.json`);
}

function globalPath() {
  return join(getStorageRoot(), 'global.json');
}

/**
 * Resolve authentic session title from DSH projection cache or storage.
 * @param {string} sessionId
 * @returns {string|null}
 */
export function resolveSessionTitle(sessionId) {
  try {
    const base = process.env.DSH_HOME ? resolve(process.env.DSH_HOME) : join(homedir(), '.dsh');
    const projFile = join(base, 'storages', 'session_projcache', 'sessions', `${sessionId}.json`);
    if (existsSync(projFile)) {
      const raw = readFileSync(projFile, 'utf8');
      const data = JSON.parse(raw);
      const title = data.record?.rows?.title?.val;
      if (typeof title === 'string' && title.trim().length > 0) {
        return title.trim();
      }
    }
  } catch {}
  return null;
}

function atomicWriteJson(filePath, data) {
  const temp = `${filePath}.${process.pid}.${Date.now()}.${Math.random().toString(36).slice(2)}.tmp`;
  try {
    writeFileSync(temp, JSON.stringify(data, null, 2), { encoding: 'utf8', mode: 0o600 });
    renameSync(temp, filePath);
  } catch (err) {
    console.error(`[dsh-context-distill] Failed atomic write to ${filePath}:`, err.message);
  }
}

/**
 * Load global aggregate statistics.
 */
export function loadGlobalStats() {
  const file = globalPath();
  const fallback = {
    totalSessions: 0,
    totalActions: 0,
    totalTruncations: 0,
    totalReplacements: 0,
    totalReplySummaries: 0,
    totalToolCalls: 0,
    distillRate: 0,
    totalCharsSaved: 0,
    totalTokensSaved: 0,
    totalExtraOutputTokens: 0,
    totalNetTokensSaved: 0,
    cacheHitProtectionRate: 0,
    averageSavingsRate: 0
  };

  if (!existsSync(file)) return fallback;
  try {
    const raw = readFileSync(file, 'utf8');
    const parsed = JSON.parse(raw);
    const actions = parsed.totalActions || 0;
    const truncations = parsed.totalTruncations || 0;
    const replacements = parsed.totalReplacements || 0;
    const toolCalls = parsed.totalToolCalls || (actions > 0 ? actions : 0);
    const distillRate = toolCalls > 0 ? Math.min(100, Math.round(((truncations + replacements) / toolCalls) * 1000) / 10) : 0;
    const cacheHitProtectionRate = actions > 0 ? Math.round((truncations / actions) * 1000) / 10 : 0;
    const totalBefore = parsed.totalCharsBefore || (parsed.totalCharsSaved ? parsed.totalCharsSaved * 1.3 : 0);
    const averageSavingsRate = totalBefore > 0 ? Math.round((parsed.totalCharsSaved / totalBefore) * 1000) / 10 : 0;

    return {
      totalSessions: parsed.totalSessions || 0,
      totalActions: actions,
      totalTruncations: truncations,
      totalReplacements: replacements,
      totalReplySummaries: parsed.totalReplySummaries || 0,
      totalToolCalls: toolCalls,
      distillRate,
      totalCharsSaved: parsed.totalCharsSaved || 0,
      totalTokensSaved: parsed.totalTokensSaved || 0,
      totalExtraOutputTokens: parsed.totalExtraOutputTokens || 0,
      totalNetTokensSaved: parsed.totalNetTokensSaved !== undefined ? parsed.totalNetTokensSaved : (parsed.totalTokensSaved || 0),
      cacheHitProtectionRate,
      averageSavingsRate
    };
  } catch {
    return fallback;
  }
}

/**
 * Load session-specific metrics and history.
 */
export function loadSessionStats(sessionId) {
  const file = sessionPath(sessionId);
  const fallback = {
    sessionId,
    title: resolveSessionTitle(sessionId) || '',
    updatedAt: Date.now(),
    actionsCount: 0,
    truncationsCount: 0,
    replacementsCount: 0,
    replySummariesCount: 0,
    toolCallsCount: 0,
    distillRate: 0,
    charsSaved: 0,
    tokensSaved: 0,
    extraOutputTokens: 0,
    netTokensSaved: 0,
    history: []
  };

  if (!existsSync(file)) return fallback;
  try {
    const raw = readFileSync(file, 'utf8');
    const parsed = JSON.parse(raw);
    const title = parsed.title || resolveSessionTitle(sessionId) || '';
    const truncations = parsed.truncationsCount || 0;
    const replacements = parsed.replacementsCount || 0;
    const toolCalls = parsed.toolCallsCount || (truncations + replacements > 0 ? truncations + replacements : 0);
    const distillRate = toolCalls > 0 ? Math.min(100, Math.round(((truncations + replacements) / toolCalls) * 1000) / 10) : 0;
    return {
      sessionId,
      title,
      updatedAt: parsed.updatedAt || Date.now(),
      actionsCount: parsed.actionsCount || 0,
      truncationsCount: truncations,
      replacementsCount: replacements,
      replySummariesCount: parsed.replySummariesCount || 0,
      toolCallsCount: toolCalls,
      distillRate,
      charsSaved: parsed.charsSaved || 0,
      tokensSaved: parsed.tokensSaved || 0,
      extraOutputTokens: parsed.extraOutputTokens || 0,
      netTokensSaved: parsed.netTokensSaved !== undefined ? parsed.netTokensSaved : (parsed.tokensSaved || 0),
      history: Array.isArray(parsed.history) ? parsed.history : []
    };
  } catch {
    return fallback;
  }
}

/**
 * Record a tool execution for trigger rate computation.
 */
export function recordToolCall({ sessionId, sessionTitle = '', toolName = '' }) {
  if (!sessionId) return;
  const session = loadSessionStats(sessionId);
  if (sessionTitle && !session.title) {
    session.title = sessionTitle;
  } else if (!session.title) {
    session.title = resolveSessionTitle(sessionId) || '';
  }
  session.updatedAt = Date.now();
  session.toolCallsCount = (session.toolCallsCount || 0) + 1;
  const truncations = session.truncationsCount || 0;
  const replacements = session.replacementsCount || 0;
  session.distillRate = session.toolCallsCount > 0 ? Math.min(100, Math.round(((truncations + replacements) / session.toolCallsCount) * 1000) / 10) : 0;
  atomicWriteJson(sessionPath(sessionId), session);

  // Update global tool calls
  const file = globalPath();
  let rawGlobal = {};
  if (existsSync(file)) {
    try { rawGlobal = JSON.parse(readFileSync(file, 'utf8')) || {}; } catch {}
  }
  rawGlobal.totalToolCalls = (rawGlobal.totalToolCalls || 0) + 1;
  atomicWriteJson(file, rawGlobal);
}

/**
 * Record one distillation event (tool result truncation, full replacement, or reply summary).
 * Updates session log and global aggregate counters atomically.
 */
export function recordDistillAction({
  sessionId,
  sessionTitle = '',
  seq,
  toolName = '',
  callId = '',
  mode = 'truncate', // 'truncate' | 'replace' | 'reply'
  charsBefore = 0,
  charsAfter = 0,
  keepChars = 0,
  keepLines = null,
  isError = false,
  cascade = false,
  trigger = 'autonomous',
  summary = ''
}) {
  if (!sessionId) return;

  // Truthful-sizes guard (问题 4): a `compress` event (truncate/replace) that did NOT
  // actually shrink the content must never be booked as a compression. We observed
  // run_code replace 112 -> 185 recorded as `saved`. For compress modes, clamp
  // charsAfter to never fall below charsBefore so charsSaved is exactly 0 and mark
  // it non-compressing. Reply projection is intentionally allowed to grow: its saved
  // amount is measured separately against the ORIGINAL reply (decision.messages), not
  // against the framed memo banner, so it legitimately reports a positive delta.
  const isCompressMode = mode === 'truncate' || mode === 'replace';
  const actuallyCompressed = !isCompressMode || charsAfter < charsBefore;
  const effectiveAfter = isCompressMode && charsAfter >= charsBefore ? charsBefore : charsAfter;
  const charsSaved = Math.max(0, charsBefore - effectiveAfter);
  const inputTokensSaved = Math.round(charsSaved / 3.5);
  const summaryLength = summary ? summary.length : 0;
  const extraOutputTokens = Math.round(summaryLength / 3.5);
  const netTokensSaved = Math.max(0, inputTokensSaved - extraOutputTokens);
  const now = Date.now();

  // 1. Update session storage
  const session = loadSessionStats(sessionId);
  if (sessionTitle && !session.title) {
    session.title = sessionTitle;
  } else if (!session.title) {
    session.title = resolveSessionTitle(sessionId) || '';
  }
  session.updatedAt = now;
  session.actionsCount += 1;
  if (mode === 'truncate') session.truncationsCount += 1;
  else if (mode === 'replace') session.replacementsCount += 1;
  else if (mode === 'reply') session.replySummariesCount += 1;

  session.charsSaved += charsSaved;
  session.tokensSaved += inputTokensSaved;
  session.extraOutputTokens = (session.extraOutputTokens || 0) + extraOutputTokens;
  session.netTokensSaved = (session.netTokensSaved || 0) + netTokensSaved;

  const entry = {
    id: `${seq || 'step'}_${now}_${Math.random().toString(36).slice(2, 6)}`,
    timestamp: now,
    seq,
    toolName,
    callId,
    mode,
    isError: Boolean(isError),
    cascade: Boolean(cascade),
    trigger: trigger || 'autonomous',
    charsBefore,
    charsAfter: effectiveAfter,
    charsSaved,
    compressed: actuallyCompressed,
    tokensSaved: inputTokensSaved,
    extraOutputTokens,
    netTokensSaved,
    keepChars,
    keepLines,
    summary: summary ? String(summary).slice(0, 4000) : ''
  };

  session.history.unshift(entry);
  if (session.history.length > 300) {
    session.history.length = 300; // retain up to 300 recent entries for deep analysis
  }
  atomicWriteJson(sessionPath(sessionId), session);

  // 2. Update global aggregate
  const global = loadGlobalStats();
  const file = globalPath();
  let rawGlobal = {};
  if (existsSync(file)) {
    try { rawGlobal = JSON.parse(readFileSync(file, 'utf8')) || {}; } catch {}
  }

  // Count unique sessions (excluding test files)
  try {
    const files = readdirSync(getSessionsDir()).filter(f => f.endsWith('.json') && !f.startsWith('test_') && !f.startsWith('test-'));
    rawGlobal.totalSessions = files.length;
  } catch {
    rawGlobal.totalSessions = (rawGlobal.totalSessions || 0) + (session.actionsCount === 1 ? 1 : 0);
  }

  rawGlobal.totalActions = (rawGlobal.totalActions || 0) + 1;
  if (mode === 'truncate') rawGlobal.totalTruncations = (rawGlobal.totalTruncations || 0) + 1;
  else if (mode === 'replace') rawGlobal.totalReplacements = (rawGlobal.totalReplacements || 0) + 1;
  else if (mode === 'reply') rawGlobal.totalReplySummaries = (rawGlobal.totalReplySummaries || 0) + 1;

  rawGlobal.totalCharsBefore = (rawGlobal.totalCharsBefore || 0) + charsBefore;
  rawGlobal.totalCharsSaved = (rawGlobal.totalCharsSaved || 0) + charsSaved;
  rawGlobal.totalTokensSaved = (rawGlobal.totalTokensSaved || 0) + inputTokensSaved;
  rawGlobal.totalExtraOutputTokens = (rawGlobal.totalExtraOutputTokens || 0) + extraOutputTokens;
  rawGlobal.totalNetTokensSaved = (rawGlobal.totalNetTokensSaved || 0) + netTokensSaved;

  atomicWriteJson(file, rawGlobal);
}

/**
 * Recompute global aggregate statistics from authentic non-test session records.
 */
export function rebuildGlobalStats() {
  const dir = getSessionsDir();
  const file = globalPath();
  const summary = {
    totalSessions: 0,
    totalActions: 0,
    totalTruncations: 0,
    totalReplacements: 0,
    totalReplySummaries: 0,
    totalCharsBefore: 0,
    totalCharsSaved: 0,
    totalTokensSaved: 0
  };

  if (existsSync(dir)) {
    try {
      const files = readdirSync(dir).filter(f => f.endsWith('.json') && !f.startsWith('test_') && !f.startsWith('test-'));
      summary.totalSessions = files.length;
      for (const f of files) {
        try {
          const raw = readFileSync(join(dir, f), 'utf8');
          const s = JSON.parse(raw);
          if (s) {
            summary.totalActions += (s.actionsCount || 0);
            summary.totalTruncations += (s.truncationsCount || 0);
            summary.totalReplacements += (s.replacementsCount || 0);
            summary.totalReplySummaries += (s.replySummariesCount || 0);
            summary.totalCharsSaved += (s.charsSaved || 0);
            summary.totalTokensSaved += (s.tokensSaved || 0);
            if (Array.isArray(s.history)) {
              for (const h of s.history) {
                summary.totalCharsBefore += (h.charsBefore || 0);
              }
            }
          }
        } catch {}
      }
    } catch {}
  }

  atomicWriteJson(file, summary);
  return summary;
}

/**
 * Load summaries of all recorded sessions, sorted by last update descending.
 */
export function loadAllSessionsSummary(historyLimit = 100) {
  const dir = getSessionsDir();
  if (!existsSync(dir)) return [];
  try {
    const files = readdirSync(dir).filter(f => f.endsWith('.json') && !f.startsWith('test_') && !f.startsWith('test-'));
    const list = [];
    for (const file of files) {
      try {
        const raw = readFileSync(join(dir, file), 'utf8');
        const s = JSON.parse(raw);
        if (s && s.sessionId) {
          const title = s.title || resolveSessionTitle(s.sessionId) || s.sessionId;
          const truncations = s.truncationsCount || 0;
          const replacements = s.replacementsCount || 0;
          const toolCalls = s.toolCallsCount || (truncations + replacements > 0 ? truncations + replacements : 0);
          const distillRate = toolCalls > 0 ? Math.min(100, Math.round(((truncations + replacements) / toolCalls) * 1000) / 10) : 0;
          list.push({
            sessionId: s.sessionId,
            title,
            updatedAt: s.updatedAt || 0,
            actionsCount: s.actionsCount || 0,
            truncationsCount: truncations,
            replacementsCount: replacements,
            replySummariesCount: s.replySummariesCount || 0,
            toolCallsCount: toolCalls,
            distillRate,
            charsSaved: s.charsSaved || 0,
            tokensSaved: s.tokensSaved || 0,
            history: historyLimit > 0 ? (s.history || []).slice(0, historyLimit) : (s.history || [])
          });
        }
      } catch {}
    }
    list.sort((a, b) => b.updatedAt - a.updatedAt);
    return list;
  } catch {
    return [];
  }
}

