/**
 * dsh-oswyn — HTTP WebServer API routes for DSH Web GUI.
 *
 * Exposes /api/oswyn/status and /api/oswyn/session (with backward-compatible
 * /api/context-distill/* aliases) on ctx.webServer so the Plugins Settings page
 * dashboard can query live metrics and history.
 *
 * @module dsh-oswyn/routes
 */

import { loadGlobalStats, loadSessionStats, loadAllSessionsSummary } from './storage.js';

function sendJson(res, status, data) {
  const body = JSON.stringify(data);
  res.writeHead(status, {
    'content-type': 'application/json',
    'content-length': Buffer.byteLength(body, 'utf8')
  });
  res.end(body);
}

export function registerWebRoutes(ctx, config) {
  const ws = ctx.webServer ?? ctx.get?.('webServer');
  if (!ws || typeof ws.register !== 'function') return () => {};

  const unregisters = [];

  const handleStatus = async (req, res) => {
    try {
      const globalStats = loadGlobalStats();
      const sessionsSummary = loadAllSessionsSummary();

      // Enrich session titles from live session manager if available
      try {
        const liveSessions = ctx.sessions?.list?.() || [];
        const titleMap = new Map();
        for (const s of liveSessions) {
          if (s.id) titleMap.set(s.id, s.title || s.header?.title);
        }
        for (const s of sessionsSummary) {
          if (titleMap.has(s.sessionId)) {
            s.title = titleMap.get(s.sessionId) || s.title;
          }
        }
      } catch {}

      sendJson(res, 200, {
        ok: true,
        enabled: config.enabled !== false,
        config: {
          enabled: config.enabled !== false,
          replySummaryEnabled: config.replySummaryEnabled !== false,
          hideReplySummaryInUi: config.hideReplySummaryInUi !== false,
          nudgeEnabled: config.nudgeEnabled !== false,
          nudgeThresholdChars: config.nudgeThresholdChars ?? 1000,
          nudgeThresholdLines: config.nudgeThresholdLines ?? 25,
          nudgeErrorThresholdChars: config.nudgeErrorThresholdChars ?? 400,
          nudgeErrorThresholdLines: config.nudgeErrorThresholdLines ?? 12
        },
        globalStats,
        sessions: sessionsSummary,
        diagnostic: {
          clientModules: ctx.get?.('clientModules')?.graph?.()?.entries?.map(e => e.id) ?? null,
          hasOswynInClient: (ctx.get?.('clientModules')?.graph?.()?.entries ?? []).some(e => e.id === 'dsh-oswyn'),
          loaderEntries: [...(ctx.loader?.entries?.() || [])].map(e => e.options.name)
        }
      });
    } catch (err) {
      sendJson(res, 500, { ok: false, error: err.message });
    }
  };

  const handleSession = async (req, res) => {
    try {
      const url = new URL(req.url, 'http://localhost');
      const sessionId = url.searchParams.get('id');
      if (!sessionId) {
        return sendJson(res, 400, { ok: false, error: 'Missing session id' });
      }
      const sessionStats = loadSessionStats(sessionId);
      sendJson(res, 200, { ok: true, session: sessionStats });
    } catch (err) {
      sendJson(res, 500, { ok: false, error: err.message });
    }
  };

  // Primary routes: /api/oswyn/*
  unregisters.push(ws.register({ kind: 'exact', path: '/api/oswyn/status', handler: handleStatus }));
  unregisters.push(ws.register({ kind: 'prefix', path: '/api/oswyn/session', handler: handleSession }));

  // Legacy compatibility routes: /api/context-distill/*
  unregisters.push(ws.register({ kind: 'exact', path: '/api/context-distill/status', handler: handleStatus }));
  unregisters.push(ws.register({ kind: 'prefix', path: '/api/context-distill/session', handler: handleSession }));

  return () => {
    for (const off of unregisters) {
      try { off?.(); } catch {}
    }
  };
}

