/**
 * dsh-oswyn — slash command registrations.
 *
 * Registers /oswyn and /oswyn-cache (with /distill aliases) in DSH command palette.
 *
 * @module dsh-oswyn/commands
 */

import { loadGlobalStats, loadSessionStats } from './storage.js';

function formatNumber(num) {
  if (typeof num !== 'number' || !Number.isFinite(num)) return '0';
  if (num >= 1000000) return (num / 1000000).toFixed(1) + 'M';
  if (num >= 1000) return (num / 1000).toFixed(1) + 'K';
  return num.toLocaleString();
}

function formatBytes(chars) {
  if (typeof chars !== 'number' || !Number.isFinite(chars)) return '0 B';
  if (chars >= 1048576) return (chars / 1048576).toFixed(1) + ' MB';
  if (chars >= 1024) return (chars / 1024).toFixed(1) + ' KB';
  return chars + ' chars';
}

export function registerCommands(ctx, config = {}) {
  const showDistillHandler = (invocation) => {
    const session = invocation?.agent?.session ?? invocation?.session;
    const global = loadGlobalStats();
    const currentStats = session?.id ? loadSessionStats(session.id) : null;

    const lines = [
      '### ⚡ DSH-OSWYN (Only See What You Need)',
      '',
      '**全局精炼收益 (Global Metrics)**:',
      `- 累计节省 Token: ~${formatNumber(global.totalTokensSaved)}`,
      `- 累计瘦身容量: ${formatBytes(global.totalCharsSaved)}`,
      `- 前缀缓存保护命中率: ${global.cacheHitProtectionRate}% (${global.totalTruncations}/${global.totalActions})`,
      `- 助手回复双轨精炼: ${global.totalReplySummaries} 次`,
