        `- 前缀截断保护: ${currentStats.truncationsCount} 次`,
        `- 全量替换摘要: ${currentStats.replacementsCount} 次`,
        `- 助手回复精炼: ${currentStats.replySummariesCount} 次`,
        `- 最近操作数: ${currentStats.history.length}`
      );

      if (Array.isArray(currentStats.history) && currentStats.history.length > 0) {
        lines.push('', '**近期精炼流水明细:**');
        const list = currentStats.history.slice(0, 8);
        for (const h of list) {
