    description: 'Show KV-cache preservation rate and prefix-cache stability',
    handler: showCacheHandler
  });
  ctx.commands?.register?.({
    name: 'distill-cache',
    description: 'Show KV-cache preservation rate (alias)',
    handler: showCacheHandler
  });
