102: const pointAt = (pts: Pt[], t: number): Pt => {
103:   if (t <= 0) return pts[0];
104:   const segs = pts.slice(1).map((p, i) => Math.hypot(p.x - pts[i].x, p.y - pts[i].y));
105:   const total = segs.reduce((a, b) => a + b, 0);
106:   let left = t * total;
107:   for (let i = 0; i < segs.length; i += 1) {
108:     if (left <= segs[i] || i === segs.length - 1) {
109:       const r = segs[i] === 0 ? 0 : cl(left / segs[i]);
110:       return { x: pts[i].x + (pts[i + 1].x - pts[i].x) * r, y: pts[i].y + (pts[i + 1].y - pts[i].y) * r };
111:     }
112:     left -= segs[i];
113:   }
114:   return pts[pts.length - 1];
115: };
