test('Dual-Track Assistant Reply Projection: rewrites historical assistant messages in decision.messages for next turns', async () => {
  const { apply } = await import('../lib/index.js');
  let preStepHook = null;
  const mockCtx = {
    sessions: {},
    tools: { register: () => {} },
    on: (evt, handler) => {
      if (evt === 'agent/pre-step') preStepHook = handler;
    },
    logger: { info: () => {}, warn: () => {}, debug: () => {} }
  };

  apply(mockCtx, {
    enabled: true,
    replySummaryEnabled: true,
    nudgeEnabled: false
  });

  const fullAssistantText = [
    'Hello user! Here is a very long 2000-character explanation of everything done.',
    'It includes lots of markdown tables and cards that the user sees in Web UI.',
    '\`\`\`dsh-reply-summary',
    '- Verified lib/index.js:300-350 dual-track projection',
    '- All 7 unit tests passed',
    '\`\`\`'
  ].join('\\n');

  const incomingDecision = {
    kind: 'enter',
    messages: [
      {
        role: 'assistant',
        content: [
          { type: 'text', text: fullAssistantText },
          { type: 'tool-call', id: 'call_123', name: 'bash', arguments: '{}' }
        ]
      },
      {
        role: 'user',
        content: [{ type: 'text', text: 'What is the next step?' }]
      }
    ]
  };

  const result = await preStepHook({
    agent: {},
    messages: incomingDecision.messages,
    signal: { aborted: false }
  }, async () => incomingDecision);

  assert.equal(result.messages.length, 2);
  const projectedAssistantMsg = result.messages[0];
  assert.equal(projectedAssistantMsg.role, 'assistant');
  // First block is the distilled memo
  const textContent = projectedAssistantMsg.content[0].text;
  assert.ok(textContent.includes('[oswyn: Previous assistant reply distilled'));
  assert.ok(textContent.includes('Verified lib/index.js:300-350'));
  assert.ok(!textContent.includes('very long 2000-character explanation'), 'Original long text must be omitted from LLM context');
  // Second block is the preserved tool-call
  assert.equal(projectedAssistantMsg.content[1].type, 'tool-call');
  assert.equal(projectedAssistantMsg.content[1].id, 'call_123');
});`
