				...config,
				checkRegistry: check || currentConfig().checkRegistry,
				...(signal === undefined ? {} : { signal }),
			});
			if (fallbackSnapshot.ok) {
				inventory = fallbackSnapshot;
				inventoryAt = Date.now();
				return fallbackSnapshot;
			}
		}
