					// detached helper relaunches it, so registry updates load.
					try {
						restartApplication();
						return "Restart requested: DeepSeek Harness will quit gracefully and relaunch automatically. This process ends now — expect the session to reconnect.";
					} catch (error) {
						return `Restart failed: ${error?.message ?? String(error)}`;
					}
				}
				default:
					return `Unknown action ${JSON.stringify(action)}. Expected one of: ${ACTIONS.join(", ")}.`;
			}
		},
