older: 'Search section name, prompt content or key...',\\n        insertRule: '➕ Insert rule',\\n        previewPrompt: '👀 Preview full prompt',\\n        refresh: '🔄 Refresh',\\n        knownSections: 'Known sections: ',\\n        sectionsInPreset: 'Defined sections [{preset}]: ',\\n        enabledCount: 'Enabled: ',\\n        customCount: 'Custom insertions: ',\\n        estTokens: 'Est. tokens: ',\\n        supportedVars: 'Variables: ',\\n        flowTitle: '📋 Assembled prompt execution flow',\\n        flowBadge: '{count} nodes',\\n        flowDesc: 'Sorted strictly according to real LLM prompt assembly sequence',\\n        loadingPrompt: '⚡ Loading prompt data...',\\n        noMatchingSections: 'No matching prompt sections found',\\n        customRulesGroup: '✨ Custom insertions',\\n        editContent: '✏️ Edit content',\\n        editOnDefault: '✏️ Edit on default',\\n        resetDefault: '🔄 Reset default',\\n        insertBefore: '⬆️ Insert before',\\n        insertAfter: '⬇️ Insert after',\\n        expandFull: '📖 Expand full text',\\n        collapse: 'Collapse',\\n        viewDiff: '🔍 View diff with default',\\n        hideDiff: 'Hide diff',\\n        saveChanges: '💾 Save changes',\\n        cancel: 'Cancel',\\n        restoreDefault: 'Restore system default',\\n        insertVarHint: 'Click to insert template variable: ',\\n        overriddenTag: 'Custom override',\\n        defaultSystemTag: 'System default',\\n        noOriginalText: '(No original prompt text)',\\n        insertModalTitle: '➕ Insert custom prompt rule',\\n        ruleNameLabel: 'Rule name / identifier:',\\n        ruleNamePlaceholder: 'e.g. Security guidelines, Role prompt',\\n        targetPresetLabel: 'Target preset:',\\n        positionLabel: 'Position:',\\n        posAfter: 'After target section (After)',\\n        posBefore: 'Before target section (Before)',\\n        posStart: 'At beginning (At Start)',\\n        posEnd: 'At end (At End)',\\n        anchorLabel: 'Anchor target section:',\\n        contentLabel: 'Prompt markdown:',\\n        quickInsertVar: 'Insert variable:',\\n        contentPlaceholder: 'Enter your custom prompt markdown here... Supports {{model}}, {{provider}}, {{cwd}}',\\n        contentTip: '💡 Tip: Enter placeholders like {{model}}, {{provider}}, {{cwd}} to dynamically substitute values during assembly.',\\n        confirmInsert: 'Confirm insert',\\n        previewModalTitle: '👀 Full assembled prompt preview ({preset})',\\n        totalSections: 'Total sections: {count}',\\n        totalChars: 'Total characters: {count}',\\n        estTokensShort: 'Est. Tokens: ~{tokens}',\\n        varsInterpolated: 'Variables evaluated with live simulation',\\n        copyAll: '📋 Copy all',\\n        copied: '✅ Copied to clipboard',\\n        close: 'Close',\\n        deleteRule: '🗑️ Delete',\\n        varModel: 'Current model',\\n        varProvider: 'Provider',\\n        varCwd: 'Working directory'\\n      }\\n    }\\n\\n    function useLocaleListener(ctx) {\\n      var locale = ctx && ctx.get ? ctx.get('locale') : null\\n      var state = React.useState(0)\\n      var setTick = state[1]\\n      React.useEffect(function () {\\n        if (!locale || typeof locale.subscribe !== 'function') return\\n        return locale.subscribe(function () {\\n          setTick(function (n) { return n + 1 })\\n        })\\n      }, [locale])\\n    }\\n\\n    function createTranslator(ctx) {\\n      var locale = ctx && ctx.get ? ctx.get('locale') : null\\n      if (locale && typeof locale.bind === 'function') {\\n        return locale.bind(NS)\\n      }\\n      var active = (locale && locale.getSnapshot) ? locale.getSnapshot().active : 'zh'\\n      var dict = DICTS[active] || DICTS.en || DICTS.zh\\n      return function (key, params) {\\n        var val = dict[key] || DICTS.en[key] || DICTS.zh[key] || key\\n        if (params) {\\n          return val.replace(/\\\\\\\\{(\\\\\\\\w+)\\\\\\\\}/g, function (m, k) { return k in params ? String(params[k]) : m })\\n        }\\n        return val\\n      }\\n    }\\n`;\\n\\ncontent = content.replace(\\\"var API_ROUTE = '/api/dsh-prompt-gate/data'\\\", \\\"var API_ROUTE = '/api/dsh-prompt-gate/data'\\\" + headerI18n);\\n\\n// 2. In PromptGateCard(props)\\ncontent = content.replace(\\n  'function PromptGateCard(props) {',\\n  'function PromptGateCard(props) {\\\\n      useLocaleListener(props.ctx)\\\\n      var t = props.t || createTranslator(props.ctx)'\\n);\\n\\n// Header title & desc\\ncontent = content.replace(\\n  `el('div', { style: { fontWeight: 700, fontSize: '18px', color: 'var(--dsw-alias-label-primary, #ffffff)' } },\\\\n              '🧠 系统提示词管理 (System Prompt Gate)'\\\\n            ),`,\\n  `el('div', { style: { fontWeight: 700, fontSize: '18px', color: 'var(--dsw-alias-label-primary, #ffffff)' } },\\\\n              t('headTitle')\\\\n            ),`\\n);\\n\\ncontent = content.replace(\\n  `'按实际装配顺序查看原提示词，支持在原提示词上修改、切换预设、使用 {{model}} 等变量占位符，并在任意位置插入定制规则。'`,\\n  `t('headDesc')`\\n);\\n\\ncontent = content.replace(\\n  `label: enabled ? '全局开启' : '全局停用',`,\\n  `label: enabled ? t('enabledGlobal') : t('disabledGlobal'),`\\n);\\n\\ncontent = content.replace(\\n  `el('span', { style: { fontSize: '12px', fontWeight: 600, color: '#94a3b8' } }, '🎯 当前预设:')`,\\n  `el('span', { style: { fontSize: '12px', fontWeight: 600, color: '#94a3b8' } }, t('currentPreset'))`\\n);\\n\\ncontent = content.replace(\\n  `p.id === 'all' ? '🌐 全部预设 (全局)' : ('⚡ ' + p.name + (p.isDefault ? ' (默认)' : ''))`,\\n  `p.id === 'all' ? t('allPresets') : ('⚡ ' + p.name + (p.isDefault ? t('defaultTag') : ''))`\\n);\\n\\ncontent = content.replace(\\n  `'📋 按实际顺序展示 (推荐)'`,\\n  `t('viewSequence')`\\n);\\n\\ncontent = content.replace(\\n  `'🗂️ 按来源分类展示'`,\\n  `t('viewCategory')`\\n);\\n\\ncontent = content.replace(\\n  `placeholder: '搜索段落名、提示词内容或标识...',`,\\n  `placeholder: t('searchPlaceholder'),`\\n);\\n\\ncontent = content.replace(\\n  `'➕ 新增提示词插入'`,\\n  `t('insertRule')`\\n);\\n\\ncontent = content.replace(\\n  `'👀 预览装配全文'`,\\n  `t('previewPrompt')`\\n);\\n\\ncontent = content.replace(\\n  `'🔄 刷新'`,\\n  `t('refresh')`\\n);\\n\\ncontent = content.replace(\\n  `'📋 实际装配执行顺序 (Top-to-Bottom Prompt Flow)'`,\\n  `t('flowTitle')`\\n);\\n\\ncontent = content.replace(\\n  `orderedFlow.length + ' 个装配节点'`,\\n  `t('flowBadge', { count: orderedFlow.length })`\\n);\\n\\ncontent = content.replace(\\n  `'完全按照大模型接收提示词的真实先后次序排序'`,\\n  `t('flowDesc')`\\n);\\n\\ncontent = content.replace(\\n  `liveData.status === 'loading' ? '⚡ 正在加载系统提示词数据...' : '没有匹配的提示词段落'`,\\n  `liveData.status === 'loading' ? t('loadingPrompt') : t('noMatchingSections')`\\n);\\n\\ncontent = content.replace(\\n  `'✨ 自定义插入规则 (Custom Insertions)'`,\\n  `t('customRulesGroup')`\\n);\\n\\n// Actions in renderSectionItem\\ncontent = content.replace(\\n  `hasOverride ? '✏️ 修改内容' : '✏️ 在原词上编辑'`,\\n  `hasOverride ? t('editContent') : t('editOnDefault')`\\n);\\n\\ncontent = content.replace(\\n  `'🔄 还原默认'`,\\n  `t('resetDefault')`\\n);\\n\\ncontent = content.replace(\\n  `'⬆️ 之前插入'`,\\n  `t('insertBefore')`\\n);\\n\\ncontent = content.replace(\\n  `'⬇️ 之后插入'`,\\n  `t('insertAfter')`\\n);\\n\\ncontent = content.replace(\\n  `isExpanded ? '收起' : '📖 查看完整内容'`,\\n  `isExpanded ? t('collapse') : t('expandFull')`\\n);\\n\\ncontent = content.replace(\\n  `isShowOrig ? '隐藏对比' : '🔍 查看与原词对比'`,\\n  `isShowOrig ? t('hideDiff') : t('viewDiff')`\\n);\\n\\ncontent = content.replace(\\n  `'💾 保存修改'`,\\n  `t('saveChanges')`\\n);\\n\\ncontent = content.replace(\\n  `'取消'`,\\n  `t('cancel')`\\n);\\n\\ncontent = content.replace(\\n  `'恢复系统默认原提示词'`,\\n  `t('restoreDefault')`\\n);\\n\\ncontent = content.replace(\\n  `'可点击插入动态变量：'`,\\n  `t('insertVarHint')`\\n);\\n\\ncontent = content.replace(\\n  `'已自定义覆盖'`,\\n  `t('overriddenTag')`\\n);\\n\\ncontent = content.replace(\\n  `'系统默认'`,\\n  `t('defaultSystemTag')`\\n);\\n\\n// Modal\\ncontent = content.replace(\\n  `'➕ 在任意位置插入系统提示词'`,\\n  `t('insertModalTitle')`\\n);\\n\\ncontent = content.replace(\\n  `'提示词名称 / 标识:'`,\\n  `t('ruleNameLabel')`\\n);\\n\\ncontent = content.replace(\\n  `placeholder: '例如: 安全编码守则、专属角色要求',`,\\n  `placeholder: t('ruleNamePlaceholder'),`\\n);\\n\\ncontent = content.replace(\\n  `'生效预设 (Preset):'`,\\n  `t('targetPresetLabel')`\\n);\\n\\ncontent = content.replace(\\n  `'插入方式 (Position):'`,\\n  `t('positionLabel')`\\n);\\n\\ncontent = content.replace(\\n  `el('option', { value: 'after' }, '紧接在目标段落之后 (After)'),\\\\n                    el('option', { value: 'before' }, '紧接在目标段落之前 (Before)'),\\\\n                    el('option', { value: 'start' }, '置于提示词最前 (At Start)'),\\\\n                    el('option', { value: 'end' }, '置于提示词最后 (At End)')`,\\n  `el('option', { value: 'after' }, t('posAfter')),\\\\n                    el('option', { value: 'before' }, t('posBefore')),\\\\n                    el('option', { value: 'start' }, t('posStart')),\\\\n                    el('option', { value: 'end' }, t('posEnd'))`\\n);\\n\\ncontent = content.replace(\\n  `'锚点目标段落 (Target Section):'`,\\n  `t('anchorLabel')`\\n);\\n\\ncontent = content.replace(\\n  `'提示词正文内容 (Markdown):'`,\\n  `t('contentLabel')`\\n);\\n\\ncontent = content.replace(\\n  `'快捷插入变量:'`,\\n  `t('quickInsertVar')`\\n);\\n\\ncontent = content.replace(\\n  `placeholder: '输入你想插入的提示词内容，例如：\\\\\\\\n## 安全规范\\\\\\\\n当前处于 {{model}} 模型环境，严禁向外部泄露内部敏感信息...',`,\\n  `placeholder: t('contentPlaceholder'),`\\n);\\n\\ncontent = content.replace(\\n  `'💡 提示：在提示词中输入 {{model}}、{{provider}}、{{cwd}} 等占位符，DSH 装配时将自动替换为实时变量值。'`,\\n  `t('contentTip')`\\n);\\n\\ncontent = content.replace(\\n  `el('button', {\\\\n                className: 'dsh-pg-btn dsh-pg-btn-primary',\\\\n                type: 'button',\\\\n                onClick: handleAddInsertion,\\\\n              }, '确认插入')`,\\n  `el('button', {\\\\n                className: 'dsh-pg-btn dsh-pg-btn-primary',\\\\n                type: 'button',\\\\n                onClick: handleAddInsertion,\\\\n              }, t('confirmInsert'))`\\n);\\n\\n// Preview modal\\ncontent = content.replace(\\n  `'👀 完整提示词装配预览 (' + previewData.preset + ')'`,\\n  `t('previewModalTitle', { preset: previewData.preset })`\\n);\\n\\ncontent = content.replace(\\n  `'段落总数: ' + (previewData.sections || []).length`,\\n  `t('totalSections', { count: (previewData.sections || []).length })`\\n);\\n\\ncontent = content.replace(\\n  `'总字符数: ' + (previewData.rendered || '').length`,\\n  `t('totalChars', { count: (previewData.rendered || '').length })`\\n);\\n\\ncontent = content.replace(\\n  `'预估 Tokens: ~' + Math.ceil((previewData.rendered || '').length / 3)`,\\n  `t('estTokensShort', { tokens: Math.ceil((previewData.rendered || '').length / 3) })`\\n);\\n\\ncontent = content.replace(\\n  `'变量已完成实时插值模拟'`,\\n  `t('varsInterpolated')`\\n);\\n\\ncontent = content.replace(\\n  `copied ? '✅ 已复制到剪贴板' : '📋 复制全部'`,\\n  `copied ? t('copied') : t('copyAll')`\\n);\\n\\ncontent = content.replace(\\n  `'关闭'`,\\n  `t('close')`\\n);\\n\\n// Exports and slots\\ncontent = content.replace(\\n  \\\"exports.inject = ['slots', 'configForms']\\\",\\n  \\\"exports.inject = ['slots', 'configForms', 'locale']\\\"\\n);\\n\\ncontent = content.replace(\\n  `      ensureStyles()\\n      var slots = ctx.get('slots')\\n      var configForms = ctx.get('configForms')\\n      if (!slots || typeof slots.inject !== 'function' ||\\n          !configForms || typeof configForms.get !== 'function' ||\\n          typeof configForms.whileServed !== 'function') return`,\\n  `      ensureStyles()\\n      var slots = ctx.get('slots')\\n      var configForms = ctx.get('configForms')\\n      var locale = ctx.get('locale')\\n      if (!slots || typeof slots.inject !== 'function' ||\\n          !configForms || typeof configForms.get !== 'function' ||\\n          typeof configForms.whileServed !== 'function') return\\n\\n      if (locale && typeof locale.register === 'function') {\\n        ctx.effect(function () {\\n          return locale.register(NS, DICTS)\\n        }, 'prompt-gate: dictionaries')\\n      }`\\n);\\n\\ncontent = content.replace(\\n  `            return slots.register({\\n              name: 'settings.section',\\n              id: 'prompt-gate',\\n              label: '提示词管理',\\n              order: 22,\\n            }, function () {\\n              return el('div', { style: { padding: '16px 20px', maxWidth: '960px', margin: '0 auto' } },\\n                el(PromptGateCard, { form: store })\\n              )\\n            })`,\\n  `            return slots.register({\\n              name: 'settings.section',\\n              id: 'prompt-gate',\\n              locale: NS,\\n              label: function () { return createTranslator(ctx)('sectionTitle') },\\n              order: 22,\\n            }, function (props) {\\n              return el('div', { style: { padding: '16px 20px', maxWidth: '960px', margin: '0 auto' } },\\n                el(PromptGateCard, { form: store, ctx: ctx, t: (props && props.t) || createTranslator(ctx) })\\n              )\\n            })`\\n);\\n\\ncontent = content.replace(\\n  `            return slots.register({\\n              name: 'plugins.bundle.config',\\n              key: 'dsh-prompt-gate',\\n              label: 'Prompt Gate',\\n            }, function () {\\n              return el(PromptGateCard, { form: store })\\n            })`,\\n  `            return slots.register({\\n              name: 'plugins.bundle.config',\\n              key: 'dsh-prompt-gate',\\n              locale: NS,\\n              label: function () { return createTranslator(ctx)('bundleTitle') },\\n            }, function (props) {\\n              return el(PromptGateCard, { form: store, ctx: ctx, t: (props && props.t) || createTranslator(ctx) })\\n            })`\\n);\\n\\nfs.writeFileSync(filePath, content, 'utf8');\\nconsole.log('adapt-prompt-gate applied successfully');\\n\"}"}
