1	/**
2	 * dsh-oswyn/core/markers — SINGLE SOURCE OF TRUTH for the [oswyn-meta: ...] machine marker.
3	 *
4	 * Pure module: no node:fs, no node:path, no ctx, no side effects.
5	 *
6	 * Marker form (prepended to the first line of a rewritten tool result):
7	 *   [oswyn-meta: before=<N> after=<M> keep=<K> mode=<truncate|replace|discard> seq=<S>]
8	 *
9	 * IMPORTANT: The frontend (client) copies MARKER_RE verbatim. Keep this regex
10	 * stable and simple — do not reformat it without bumping both sides together.
11	 *
12	 * @module dsh-oswyn/core/markers
13	 */
14	
15	/** Accepted rewrite modes. */
16	export const MODES = Object.freeze(['truncate', 'replace', 'discard']);
17	
18	/**
19	 * Canonical marker regex. Must remain a stable, simple, global-flag-free shape
20	 * so the client can reuse it byte-for-byte.
21	 * Groups: 1=before, 2=after, 3=keep, 4=mode, 5=seq
22	 */
23	export const MARKER_RE = /\[oswyn-meta: before=(\d+|\?) after=(\d+|\?) keep=(\d+|\?) mode=(truncate|replace|discard) seq=([^\]\s]+)\]/;
24	
25	/** Global variant for locate/replace-all in a blob of text. */
26	export const MARKER_RE_GLOBAL = /\[oswyn-meta: before=(\d+|\?) after=(\d+|\?) keep=(\d+|\?) mode=(truncate|replace|discard) seq=([^\]\s]+)\]/g;
27	
28	function normalizedMode(mode) {
29	  return MODES.includes(mode) ? mode : 'replace';
30	}
31	
32	function numOrQ(v) {
33	  return Number.isFinite(v) ? String(v) : '?';
34	}
35	
36	/**
37	 * Encode a machine marker string.
38	 * @param {{before:number, after:number, keep:number, mode:string, seq:(number|string)}} meta
39	 * @returns {string}
40	 */
41	export function encodeMeta(meta = {}) {
42	  const before = numOrQ(meta.before);
43	  const after = numOrQ(meta.after);
44	  const keep = numOrQ(meta.keep === undefined ? meta.keepChars : meta.keep);
45	  const mode = normalizedMode(meta.mode);
46	  const seq = meta.seq === undefined || meta.seq === null ? '?' : String(meta.seq);
47	  return `[oswyn-meta: before=${before} after=${after} keep=${keep} mode=${mode} seq=${seq}]`;
48	}
49	
50	/**
51	 * Parse a machine marker out of a text blob (first match).
52	 * @param {string} text
53	 * @returns {{before:number|null, after:number|null, keep:number|null, mode:string, seq:string|null}|null}
54	 */
55	export function parseMeta(text) {
56	  if (typeof text !== 'string') return null;
57	  const m = text.match(MARKER_RE);
58	  if (!m) return null;
59	  const toNum = (s) => (s === '?' ? null : parseInt(s, 10));
60	  return {
61	    before: toNum(m[1]),
62	    after: toNum(m[2]),
63	    keep: toNum(m[3]),
64	    mode: m[4],
65	    seq: m[5] === '?' ? null : m[5]
66	  };
67	}
68	
69	/**
70	 * True when the text already carries an oswyn marker (used for idempotency).
71	 * @param {string} text
72	 */
73	export function hasMeta(text) {
74	  return typeof text === 'string' && MARKER_RE.test(text);
75	}

