1	/**
2	 * dsh-oswyn/core/parse — pure markdown-fence parsers for oswyn directives.
3	 *
4	 * Pure module: no node:fs, no node:path, no ctx, no side effects.
5	 * Accepts the fence tags as explicit params (defaults from protocol.js) so this
6	 * stays free of any runtime coupling while remaining the canonical parser.
7	 *
8	 * @module dsh-oswyn/core/parse
9	 */
10	
11	const DEFAULT_SUMMARY_TAG = 'dsh-result-summary';
12	const DEFAULT_REPLY_TAG = 'dsh-reply-summary';
13	
14	function escapeRe(s) {
15	  return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
16	}
17	
18	function buildOpenRe(tag) {
19	  // Matches ```<tag> optionally followed by ": header" or bare "header" on the same line.
20	  return new RegExp('\u0060\u0060\u0060' + escapeRe(tag) + '(?::\\s*([^\\n]*)|[ \\t]*([^\\n]*))?\\n', 'g');
21	}
22	
23	function scanBlocks(text, tag) {
24	  if (typeof text !== 'string') return [];
25	  const openRe = buildOpenRe(tag);
26	  const results = [];
27	  let match;
28	  while ((match = openRe.exec(text)) !== null) {
29	    const rawHeader = (match[1] || match[2] || '').trim();
30	    const contentStart = openRe.lastIndex;
31	    const closeIdx = text.indexOf('\u0060\u0060\u0060', contentStart);
32	    if (closeIdx !== -1) {
33	      results.push({
34	        rawHeader,
35	        body: text.slice(contentStart, closeIdx).trim(),
36	        start: match.index,
37	        end: closeIdx + 3
38	      });
39	    }
40	  }
41	  return results;
42	}
43	
44	/** Locate ALL tool-result summary fenced blocks (cascade / multi-target). */
45	export function findAllSummaryBlocks(text, tag = DEFAULT_SUMMARY_TAG) {
46	  return scanBlocks(text, tag);
47	}
48	
49	/** Locate the LAST tool-result summary fenced block. */
50	export function findSummaryBlock(text, tag = DEFAULT_SUMMARY_TAG) {
51	  const all = scanBlocks(text, tag);
52	  return all.length ? all[all.length - 1] : null;
53	}
54	
55	/** Locate the LAST assistant reply summary fenced block. */
56	export function findReplySummaryBlock(text, tag = DEFAULT_REPLY_TAG) {
