61	const DIRECTIVE_LINE_RE = /^(?:seq\b|truncate\b|replace\b|discard\b|keep\b|prune-call|prune-args|prune-code|prune-failures|stub-call|cascade|clean-call)/i;
62	
63	/**
64	 * Parse a tool-result summary block (header + body) into a structured request.
65	 *
66	 * Recognized directives (header OR first body line):
67	 *   truncate keep <N> lines|chars   -> mode 'truncate'
68	 *   replace                         -> mode 'replace'
69	 *   discard                         -> mode 'discard'
70	 *   seq <N> | seq <tool_name>       -> target
71	 *   cascade / prune-failures        -> cascadePrune
72	 *   prune-call / prune-args         -> pruneCall
73	 *   stub-call                       -> stubCall (implies pruneCall)
74	 *
75	 * @returns {{
76	 *   targetSeq:(number|null), targetTool:(string|null), mode:'truncate'|'replace'|'discard',
77	 *   keepCount:(number|null), keepUnit:'chars'|'lines', cascadePrune:boolean,
78	 *   pruneCall:boolean, stubCall:boolean, summary:string, fact:string
79	 * }}
80	 */
81	export function parseSummaryBody(rawHeader, rawBody) {
82	  let targetSeq = null;
83	  let targetTool = null;
84	  let mode = 'replace';
85	  let keepCount = null;
86	  let keepUnit = 'chars';
87	  let fact = '';
88	
89	  const lines = String(rawBody || '').split('\n');
90	  const firstLine = (lines[0] || '').trim();
91	  const headerText = [String(rawHeader || '').trim(), firstLine].filter(Boolean).join(' ');
92	  const probe = headerText + '\n' + lines.join('\n');
93	
94	  // --- mode ---
95	  if (/\bdiscard\b/i.test(probe)) {
96	    mode = 'discard';
97	  } else {
98	    const truncateMatch = headerText.match(/\b(?:keep|retain|truncate)\s+(\d+)\s*(lines?|chars?|characters?)?/i);
99	    if (truncateMatch) {
100	      mode = 'truncate';
101	      keepCount = parseInt(truncateMatch[1], 10);
102	      const unit = (truncateMatch[2] || '').toLowerCase();
103	      keepUnit = unit.startsWith('line') ? 'lines' : 'chars';
104	    } else if (/\btruncate\b/i.test(probe)) {
105	      mode = 'truncate';
106	    }
107	  }
108	
109	  // --- seq target ---
110	  const seqMatch = headerText.match(/\bseq[:=\s]+(\d+)\b/i) || headerText.match(/\bseq[:=\s]+([a-zA-Z0-9_-]+)\b/i);
111	  if (seqMatch) {
112	    if (/^\d+$/.test(seqMatch[1])) targetSeq = parseInt(seqMatch[1], 10);
113	    else targetTool = seqMatch[1];
114	  }
115	
116	  // --- flags ---
117	  const cascadePrune = /\b(?:cascade|prune-failures|cascade-prune)\b/i.test(probe);
118	  const stubCall = /\bstub-call\b/i.test(probe);
119	  const pruneCall = stubCall || /\b(?:prune-call|prune-args|prune-code|clean-call)\b/i.test(probe);
120	
121	  // --- facts: body lines minus directive-only lines ---
122	  const bodyLines = lines.filter((l) => {
123	    const t = l.trim();
124	    if (!t) return false;
125	    if (DIRECTIVE_LINE_RE.test(t)) return false;
126	    // a bare directive word alone on a line
127	    if (/^(?:truncate|replace|discard)$/i.test(t)) return false;
128	    return true;
129	  });
130	  const summary = bodyLines.join('\n').trim();
131	  if (mode === 'discard') fact = summary;
132	
133	  return {
134	    targetSeq,
135	    targetTool,
136	    mode,
137	    keepCount,
138	    keepUnit,
139	    cascadePrune,
140	    pruneCall,
141	    stubCall,
142	    summary,
143	    fact
144	  };
145	}
