147	/** Parse an assistant reply summary block (optional `seq <N>` header). */
148	export function parseReplySummaryBody(rawHeader, rawBody) {
149	  let targetSeq = null;
150	  const headerMatch = String(rawHeader || '').match(/\bseq[:=\s]+(\d+)\b/i);
151	  if (headerMatch) targetSeq = parseInt(headerMatch[1], 10);
152	  return {
153	    targetSeq,
154	    summary: String(rawBody || '').trim()
155	  };
156	}

