1	/**
2	 * dsh-oswyn/core/plan — pure rewrite planner.
3	 *
4	 * Pure module: no node:fs, no node:path, no ctx, no side effects.
5	 * Computes the rewritten tool-result content blocks for a given target + parsed
6	 * directive without ever touching a session.
7	 *
8	 * @module dsh-oswyn/core/plan
9	 */
10	
11	import { encodeMeta } from './markers.js';
12	
13	const MIN_CHARS = 20;
14	
15	/** Combined plain-text length of a content-blocks array. */
16	export function textLength(blocks) {
17	  if (!Array.isArray(blocks)) return 0;
18	  let len = 0;
19	  for (const b of blocks) {
20	    if (b && b.type === 'text' && typeof b.text === 'string') len += b.text.length;
21	  }
22	  return len;
23	}
24	
25	function blockText(blocks) {
26	  if (!Array.isArray(blocks)) return '';
27	  return blocks.map((b) => (b && b.type === 'text' && typeof b.text === 'string' ? b.text : '')).join('\n');
28	}
29	
30	/** Extract the char count that the target tool result occupies today. */
31	export function measureTarget(target) {
32	  const blocks = target?.event?.data?.message?.content || target?.event?.data?.content || [];
33	  return blockText(blocks).length;
34	}
35	
36	function truncateBanner({ meta, discardedChars, summary }) {
37	  return `\n\n${meta}\n[oswyn: ... 已截断尾部 ${discardedChars} 字符以优化上下文，同时保留前缀缓存命中；完整原文可经 tool_result_recall 召回]\n\n截断部分的关键事实：\n${summary}`;
38	}
39	
40	function replaceBanner({ meta, toolName, summary, mode }) {
41	  const kind = mode === 'discard' ? '已整段丢弃，仅保留事实' : '已总结压缩，关键事实保留';
42	  return `${meta}\n[oswyn: ${toolName ? toolName + ' ' : ''}输出${kind}；完整原文保留于会话历史，可经 tool_result_recall 召回]\n\n${summary}`;
43	}
44	
45	/**
46	 * Compute the fixed-point content for truncate / replace / discard.
47	 *
48	 * For truncate the prefix is copied verbatim from index 0 so prompt cache is
49	 * preserved; the banner embeds the digits of `after`, therefore the total
50	 * length depends on the digits of `after` — iterate until self-consistent.
51	 *
52	 * @param {{seq?:number|string, event?:object}} target
53	 * @param {ReturnType<import('./parse.js').parseSummaryBody>} parsed
54	 * @param {string} [toolName]
55	 * @returns {{mode:string,before:number,after:number,keepChars:number,keepLines:(number|null),content:Array<{type:'text',text:string}>,rejected?:string}}
56	 */
57	export function plan(target, parsed = {}, toolName = '') {
58	  const origText = blockText(target?.event?.data?.message?.content || target?.event?.data?.content || []);
59	  const before = origText.length;
60	
61	  if (before <= MIN_CHARS) {
62	    return {
63	      mode: parsed.mode || 'replace',
64	      before,
65	      after: before,
66	      keepChars: 0,
67	      keepLines: null,
68	      content: null,
69	      rejected: `content size (${before}) too small to warrant distillation`
70	    };
71	  }
72	
73	  const seq = parsed.seq ?? target?.seq ?? target?.event?.seq ?? '?';
74	  const mode = parsed.mode === 'truncate' || parsed.mode === 'discard' ? parsed.mode : 'replace';
75	  const summary = (parsed.summary || '').trim();
76	
77	  if (mode === 'truncate') {
78	    // Determine cut index
79	    let cutIndex;
80	    let keepLines = null;
81	    if (parsed.keepUnit === 'lines') {
82	      const lineCount = parsed.keepCount || 50;
83	      const lines = origText.split('\n');
84	      const kept = lines.slice(0, lineCount);
85	      cutIndex = kept.join('\n').length;
86	      if (lines.length > lineCount) cutIndex += 1; // include trailing newline separator
87	      keepLines = Math.min(lineCount, lines.length);
88	    } else if (parsed.keepCount) {
89	      cutIndex = parsed.keepCount;
90	    } else {
91	      cutIndex = 2000;
92	    }
93	    cutIndex = Math.min(before, Math.max(0, cutIndex));
94	    const keepChars = cutIndex;
95	    const prefix = origText.slice(0, cutIndex);
96	    const discardedChars = Math.max(0, before - cutIndex);
97	
98	    // Fixed-point iterate so the banner's own digits are consistent.
99	    let guess = prefix.length + 200;
100	    let content = null;
101	    for (let i = 0; i < 8; i += 1) {
102	      const meta = encodeMeta({ before, after: guess, keep: keepChars, mode: 'truncate', seq });
103	      content = [{ type: 'text', text: prefix + truncateBanner({ meta, discardedChars, summary }) }];
104	      const exact = textLength(content);
105	      if (exact === guess) break;
106	      guess = exact;
107	    }
108	    const after = textLength(content);
109	    return { mode: 'truncate', before, after, keepChars, keepLines, content };
110	  }
111	
112	  // replace | discard
113	  let guess = 200;
114	  let content = null;
115	  for (let i = 0; i < 8; i += 1) {
116	    const meta = encodeMeta({ before, after: guess, keep: 0, mode, seq });
117	    content = [{ type: 'text', text: replaceBanner({ meta, toolName, summary, mode }) }];
118	    const exact = textLength(content);
119	    if (exact === guess) break;
120	    guess = exact;
121	  }
122	  const after = textLength(content);
123	  return { mode, before, after, keepChars: 0, keepLines: null, content };
124	}

