1	/**
2	 * dsh-oswyn/core/projection — pure tool-call argument projection.
3	 *
4	 * Pure module: no node:fs, no node:path, no ctx, no side effects.
5	 * Shrinks oversized `code` / `spec` arguments inside an assistant message's
6	 * tool-call blocks to a short pseudocode placeholder, leaving every other
7	 * block and field byte-for-byte intact. Idempotent and strictly non-growing.
8	 *
9	 * @module dsh-oswyn/core/projection
10	 */
11	
12	const DEFAULT_MAX_CODE_LEN = 150;
13	const DEFAULT_MAX_SPEC_LEN = 150;
14	
15	function placeholder(field, originalLen) {
16	  if (field === 'spec') {
17	    return `// [oswyn: spec 已折叠，原 ${originalLen} 字符 · 伪代码占位；完整内容见历史]`;
18	  }
19	  return `// [oswyn: code 已折叠，原 ${originalLen} 字符 · 伪代码占位；完整内容见历史]`;
20	}
21	
22	function shrinkField(value, maxLen) {
23	  if (typeof value !== 'string' || value.length <= maxLen) return { value, changed: false };
24	  return { value: placeholder(value.length > 0 ? 'code' : 'code', value.length), changed: true };
25	}
26	
27	/**
28	 * Project one parsed-arguments object: replace oversized code/spec leaves.
29	 * Returns a NEW object; never mutates input.
30	 */
31	function projectArgsObject(args, { maxCodeLen, maxSpecLen }) {
32	  if (!args || typeof args !== 'object') return { args, changed: false };
33	  const out = Array.isArray(args) ? args.slice() : { ...args };
34	  let changed = false;
35	
36	  if (typeof out.code === 'string' && out.code.length > maxCodeLen) {
37	    out.code = placeholder('code', out.code.length);
38	    changed = true;
39	  }
40	  if (typeof out.spec === 'string' && out.spec.length > maxSpecLen) {
41	    out.spec = placeholder('spec', out.spec.length);
42	    changed = true;
43	  }
44	  return { args: out, changed };
45	}
46	
47	function projectBlock(block, limits) {
48	  if (!block || block.type !== 'tool-call') return { block, changed: false };
49	  const raw = block.arguments;
50	  if (raw === undefined || raw === null) return { block, changed: false };
51	
52	  // arguments may be a JSON string or an object
53	  if (typeof raw === 'string') {
54	    let parsed;
55	    try {
56	      parsed = JSON.parse(raw);
57	    } catch {
58	      return { block, changed: false };
59	    }
60	    const { args, changed } = projectArgsObject(parsed, limits);
61	    if (!changed) return { block, changed: false };
62	    return { block: { ...block, arguments: JSON.stringify(args) }, changed: true };
63	  }
64	
65	  const { args, changed } = projectArgsObject(raw, limits);
66	  if (!changed) return { block, changed: false };
67	  return { block: { ...block, arguments: args }, changed: true };
68	}
69	
70	/**
71	 * Prune oversized tool-call arguments in a single assistant message.
72	 * Accepts either a Message ({content:[...]}) or a raw content-blocks array.
73	 * Returns a NEW value of the same shape; whatever does not change is reused.
74	 *
75	 * @param {object|Array} message
76	 * @param {{maxCodeLen?:number, maxSpecLen?:number}} [opts]
77	 * @returns {object|Array}
78	 */
79	export function pruneToolCallArgs(message, opts = {}) {
80	  const limits = {
81	    maxCodeLen: Number.isFinite(opts.maxCodeLen) ? opts.maxCodeLen : DEFAULT_MAX_CODE_LEN,
82	    maxSpecLen: Number.isFinite(opts.maxSpecLen) ? opts.maxSpecLen : DEFAULT_MAX_SPEC_LEN
83	  };
84	
85	  const asBlocks = Array.isArray(message) ? message : message?.content;
86	  if (!Array.isArray(asBlocks)) return message;
87	
88	  let touched = false;
89	  const nextBlocks = asBlocks.map((b) => {
90	    const { block, changed } = projectBlock(b, limits);
91	    if (changed) touched = true;
92	    return block;
93	  });
94	
95	  if (!touched) return message;
96	  if (Array.isArray(message)) return nextBlocks;
97	  return { ...message, content: nextBlocks };
98	}

