100	/** Build the inclusive integer range [start..end]. */
101	function denseRange(startSeq, endSeq) {
102	  const first = Math.min(startSeq, endSeq);
103	  const last = Math.max(startSeq, endSeq);
104	  const out = [];
105	  for (let s = first; s <= last; s += 1) out.push(s);
