109	/**
110	 * Replace an entire surface range [startSeq..endSeq] with a single user/message
111	 * checkpoint carrying `text`. This is the ONLY correct negative-delta path for
112	 * reply compression and whole-discard: the kernel splices every shadowed node
113	 * out of the surface, so deriveMessages() gets one short memo where N messages
114	 * used to be.
115	 *
116	 * The checkpoint data IS the message (user/message derives as event.data), and
117	 * sourceEventSeqs must cover EVERY shadowed surface node plus any of their
118	 * source refs, hence we pass the dense range.
119	 *
120	 * @param {object} session
121	 * @param {number} startSeq
122	 * @param {number} endSeq
123	 * @param {string} text
124	 * @param {{seqs?:number[], source?:object}} [opts] extra explicit source seqs
125	 * @returns {{ok:boolean, seq?:number, event?:object, reason?:string}}
126	 */
127	export function appendCheckpointReplace(session, startSeq, endSeq, text, opts = {}) {
128	  try {
129	    if (!session || typeof session.append !== 'function') {
130	      return { ok: false, reason: 'no session.append' };
131	    }
132	    const first = Math.min(startSeq, endSeq);
133	    const last = Math.max(startSeq, endSeq);
134	    if (!Number.isInteger(first) || !Number.isInteger(last) || first < 0) {
135	      return { ok: false, reason: `invalid range ${startSeq}..${endSeq}` };
136	    }
137	    const nextSeq = typeof session.seq === 'number'
138	      ? session.seq
139	      : (session.log ? session.log.length : undefined);
140	    if (typeof nextSeq === 'number' && last >= nextSeq) {
141	      return { ok: false, reason: `range end ${last} >= next seq ${nextSeq} (must reference earlier events)` };
142	    }
143	    if (!isOnSurface(session, first) || !isOnSurface(session, last)) {
144	      return { ok: false, reason: `range ${first}..${last} not fully on current surface` };
145	    }
146	    // Dense source coverage of the shadowed range; union any extra explicit seqs.
147	    const srcSet = new Set(denseRange(first, last));
148	    if (Array.isArray(opts.seqs)) {
149	      for (const s of opts.seqs) if (Number.isInteger(s) && s < first) srcSet.add(s);
150	    }
151	    const sourceEventSeqs = [...srcSet].sort((a, b) => a - b);
152	    // user/message: the event DATA *is* the message (kernel derives it directly),
153	    // and the kernel REQUIRES a non-empty string id ("lacks an identified message"
154	    // otherwise). assistant/system/developer/tool events instead nest it under
155	    // data.message — user/message is the exception.
156	    const data = {
157	      id: 'oswyn-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8),
158	      role: 'user',
159	      source: opts.source ?? { kind: 'oswyn-compaction' },
160	      content: [{ type: 'text', text: String(text) }]
161	    };
162	    const event = session.append('user/message', data, {
163	      surfaceOp: { op: 'replace', startSeq: first, endSeq: last },
164	      sourceEventSeqs
165	    });
166	    return { ok: true, seq: event.seq, event };
167	  } catch (error) {
168	    return { ok: false, reason: String(error && error.message ? error.message : error) };
169	  }
170	}

