41	  const content = assistantMsg?.content;
42	  if (typeof content === 'string') return content;
43	  if (!Array.isArray(content)) return '';
44	  return content
45	    .filter((b) => b && b.type === 'text' && typeof b.text === 'string')
46	    .map((b) => b.text)
