50	/** Resolve the callId of a tool/result event: direct source, else via sourceEventSeqs→tool/call, else callId on data. */
51	function resolveCallId(session, event) {
52	  if (!event) return '';
53	  const direct = event.data?.message?.source?.callId ?? event.data?.callId;
54	  if (typeof direct === 'string' && direct) return direct;
55	  const srcs = event.sourceEventSeqs;
56	  if (Array.isArray(srcs)) {
57	    for (const s of srcs) {
58	      const callEv = typeof session?.eventAt === 'function' ? session.eventAt(s) : null;
59	      if (callEv?.type === 'tool/call' && typeof callEv.data?.callId === 'string' && callEv.data.callId) {
60	        return callEv.data.callId;
61	      }
62	    }
63	  }
64	  return '';
