67	/** Last seq at or before `assistantSeq` whose event is a tool/result. */
68	function findLatestToolResult(session, assistantSeq) {
69	  const all = typeof session.snapshotEvents === 'function' ? session.snapshotEvents() : [];
70	  const limit = typeof assistantSeq === 'number' ? assistantSeq : Infinity;
71	  for (let i = all.length - 1; i >= 0; i -= 1) {
72	    const ev = all[i];
73	    if (ev.seq >= limit) continue;
74	    if (ev.type === 'tool/result') return ev;
75	  }
