79	/**
80	 * Resolve a parsed target directive to a concrete tool/result event.
81	 * @returns {{seq:number, event:object}|null}
82	 */
83	export function resolveTarget(session, parsed, assistantSeq) {
84	  const all = typeof session.snapshotEvents === 'function' ? session.snapshotEvents() : [];
85	  const limit = typeof assistantSeq === 'number' ? assistantSeq : Infinity;
86	
87	  // Explicit numeric seq.
88	  if (parsed.targetSeq !== null && parsed.targetSeq !== undefined) {
89	    const ev = typeof session.eventAt === 'function' ? session.eventAt(parsed.targetSeq) : null;
90	    if (ev && ev.type === 'tool/result') return { seq: ev.seq, event: ev };
91	  }
92	
93	  // By tool name (latest before the assistant message).
94	  if (parsed.targetTool) {
95	    const wanted = String(parsed.targetTool).toLowerCase();
96	    for (let i = all.length - 1; i >= 0; i -= 1) {
97	      const ev = all[i];
98	      if (ev.seq >= limit) continue;
99	      if (ev.type === 'tool/result' && (getToolName(session, ev) || '').toLowerCase() === wanted) {
100	        return { seq: ev.seq, event: ev };
101	      }
102	    }
103	  }
104	
105	  // Default: latest tool/result preceding the assistant message.
106	  const latest = findLatestToolResult(session, assistantSeq);
107	  return latest ? { seq: latest.seq, event: latest } : null;
108	}
