110	/**
111	 * Apply all oswyn fences found in an assistant message.
112	 *
113	 * @param {object} session
114	 * @param {object} assistantMsg  the assistant Message ({content:[...]})
115	 * @param {number} [assistantSeq]  seq of the assistant/message event
116	 * @param {{pruneCall?:boolean, maxCodeLen?:number, maxSpecLen?:number}} [opts]
117	 * @returns {{
118	 *   applied:Array<{seq:number,mode:string,before:number,after:number,keepChars?:number,fact?:string}>,
119	 *   replySummary:({targetSeq:(number|undefined),summary:string}|null),
120	 *   rejected:string[],
121	 *   checkpoint:({startSeq:number,endSeq:number,seq:number,count:number}|null),
122	 *   callArgProjection:({message:object,changed:boolean}|null),
123	 *   error?:string
124	 * }}
125	 */
126	export function applyFromAssistantMessage(session, assistantMsg, assistantSeq, opts = {}) {
127	  const result = {
128	    applied: [],
129	    replySummary: null,
130	    rejected: [],
131	    checkpoint: null,
132	    callArgProjection: null
133	  };
134	  try {
135	    const text = assistantText(assistantMsg);
136	
137	    // ---- 1. tool-result summary fences ----
138	    let blocks = findAllSummaryBlocks(text);
139	    if (blocks.length === 0) {
140	      const single = findSummaryBlock(text);
141	      if (single) blocks = [single];
142	    }
143	
144	    const discardTargets = [];
145	    for (const block of blocks) {
146	      const parsed = parseSummaryBody(block.rawHeader, block.body);
147	      const target = resolveTarget(session, parsed, assistantSeq);
148	      if (!target) {
149	        result.rejected.push('no target tool/result found');
150	        continue;
151	      }
152	      // Give plan() an explicit seq for the marker.
153	      const parsedWithSeq = { ...parsed, mode: parsed.mode, seq: target.seq };
154	
155	      // Only an EXPLICIT agent directive overrides retention. A fence that just
156	      // carries facts must not silently be treated as `replace`.
157	      const retention = decideRetention(target, parsed, { session });
158	      const explicit = parsed.explicitMode || null;
159	      if (explicit === null) {
160	        result.rejected.push(
161	          'no explicit directive (expected truncate keep <N> lines | replace | discard); retention would be: '
162	          + retention.action
163	        );
164	        continue;
165	      }
166	      if (explicit === 'discard' || retention.action === 'discard') {
167	        discardTargets.push({ seq: target.seq, event: target.event, text: getEventText(target.event) });
168	        continue;
169	      }
170	
171	      const before = measureTarget(target);
172	      const planResult = corePlan(target, parsedWithSeq, getToolName(session, target.event) || '');
173	      if (planResult.rejected) {
174	        result.rejected.push(planResult.rejected);
175	        continue;
176	      }
177	      const write = appendToolResultReplace(session, target.seq, planResult.content);
178	      if (!write.ok) {
179	        result.rejected.push(`tool/result replace failed: ${write.reason}`);
180	        continue;
181	      }
182	      result.applied.push({
183	        seq: target.seq,
184	        mode: planResult.mode,
185	        toolName: getToolName(session, target.event) || '',
186	        callId: resolveCallId(session, target.event),
187	        keepChars: planResult.keepChars,
188	        keepLines: planResult.keepLines ?? null,
189	        before: planResult.before,
190	        after: planResult.after
191	      });
192	
193	      // ---- prune-call / stub-call → argument projection of assistant message ----
194	      if ((parsed.pruneCall || parsed.stubCall) && opts.pruneCall !== false) {
195	        const pruned = pruneToolCallArgs(assistantMsg, {
196	          maxCodeLen: opts.maxCodeLen,
197	          maxSpecLen: opts.maxSpecLen
198	        });
199	        if (pruned && pruned !== assistantMsg) {
200	          result.callArgProjection = { message: pruned, changed: true };
201	        }
202	      }
203	    }
204	
205	    // ---- 2. discard grouping → ONE checkpoint over the span ----
206	    if (discardTargets.length > 0) {
207	      const grouped = groupDiscard(discardTargets, { session });
208	      if (grouped.ok) {
209	        // Only collapse a contiguous run that is actually on the current surface.
210	        const allOnSurface = discardTargets.every((t) => isOnSurface(session, t.seq));
211	        if (allOnSurface) {
212	          const write = appendCheckpointReplace(session, grouped.startSeq, grouped.endSeq, grouped.fact);
213	          if (write.ok) {
214	            result.checkpoint = {
215	              startSeq: grouped.startSeq,
216	              endSeq: grouped.endSeq,
217	              seq: write.seq,
218	              count: grouped.count
219	            };
220	            for (const t of discardTargets) {
221	              const before = getEventText(t.event).length;
222	              result.applied.push({
223	                seq: t.seq,
224	                mode: 'discard',
225	                toolName: getToolName(session, t.event) || '',
226	                keepLines: null,
227	                before,
228	                after: grouped.fact.length,
229	                fact: grouped.fact
230	              });
231	            }
232	          } else {
233	            result.rejected.push(`discard checkpoint failed: ${write.reason}`);
234	          }
235	        } else {
236	          result.rejected.push('discard span not fully on current surface');
237	        }
238	      } else {
239	        result.rejected.push(grouped.reason || 'discard grouping failed');
240	      }
241	    }
242	
243	    // ---- 3. reply summary → checkpoint-replace the assistant range ----
244	    const replyBlock = findReplySummaryBlock(text);
245	    if (replyBlock && opts.replySummaryEnabled !== false) {
246	      const parsed = parseReplySummaryBody(replyBlock.rawHeader, replyBlock.body);
247	      const targetSeq = parsed.targetSeq ?? assistantSeq;
248	      const summary = (parsed.summary || '').trim();
249	      if (Number.isInteger(targetSeq) && summary) {
250	        // Cover from the target assistant seq through the latest surface node
251	        // BEFORE this assistant message's own tail, i.e. replace exactly the
252	        // assistant node itself (single-node) — the safe negative-delta form.
253	        const write = appendCheckpointReplace(
254	          session,
255	          targetSeq,
256	          targetSeq,
257	          `[oswyn 双轨备忘 · 原文可召回 seq=${targetSeq}] ${summary}`
258	        );
259	        if (write.ok) {
260	          result.replySummary = { targetSeq, summary, charsBefore: text.length };
261	        } else {
262	          result.rejected.push(`reply checkpoint failed: ${write.reason}`);
263	        }
264	      }
265	    }
266	
267	    return result;
268	  } catch (error) {
269	    result.error = String(error && error.message ? error.message : error);
270	    return result;
271	  }
272	}
