274	/**
275	 * Rewrite tool-call arguments of an assistant message and return the projected
276	 * Message plus whether anything changed. Used by the E-stage index to register a
277	 * message projection (tool-call args cannot use surfaceOp).
278	 *
279	 * @param {object} session
280	 * @param {object} assistantEvent  the assistant/message event
281	 * @param {{maxCodeLen?:number, maxSpecLen?:number}} [opts]
282	 * @returns {{ok:boolean, message?:object, changed:boolean, reason?:string}}
283	 */
284	export function applyCallArgRewrite(session, assistantEvent, opts = {}) {
285	  try {
286	    const msg = assistantEvent?.data?.message;
287	    if (!msg) return { ok: false, changed: false, reason: 'no assistant message' };
288	    const pruned = pruneToolCallArgs(msg, {
289	      maxCodeLen: opts.maxCodeLen,
290	      maxSpecLen: opts.maxSpecLen
291	    });
292	    return { ok: true, message: pruned, changed: pruned !== msg };
293	  } catch (error) {
