298	/**
299	 * AUTOMATIC tool-output compression (no model fence required).
300	 *
301	 * The agent does not reliably emit dsh-result-summary fences for tool output, so
302	 * OSWYN compresses oversized tool results itself: keep the leading N lines
303	 * byte-for-byte (prompt-cache safe) and append a short structured tail, or fully
304	 * replace exploratory/failed output with a fact. Returns the applied record or null.
305	 *
306	 * @param {object} session
307	 * @param {object} event  the tool/result event
308	 * @param {{minChars?:number, keepLines?:number, replySummaryEnabled?:boolean}} [opts]
309	 */
310	export function autoCompressToolResult(session, event, opts = {}) {
311	  try {
312	    if (!session || !event || event.type !== 'tool/result') return null;
313	    const orig = getEventText(event);
314	    const minChars = Math.max(200, Number(opts.minChars) || 4000);
315	    if (!orig || orig.length < minChars) return null;
316	    if (orig.indexOf('[oswyn-meta:') >= 0) return null; // already compressed
317	    // Skip if this node is no longer on the surface (already replaced).
318	    if (typeof isOnSurface === 'function' && !isOnSurface(session, event.seq)) return null;
319	
320	    const toolName = getToolName(session, event) || '';
321	    const lines = orig.split('\n');
322	    // No silent 30-line default: auto mode keeps the configured prefix only when
323	    // it was explicitly configured, otherwise it would fight the agent's own
324	    // truncate directive (the '双层压缩' double-compression problem).
325	    const configured = Number(opts.keepLines);
326	    if (!Number.isFinite(configured) || configured <= 0) return null;
327	    const keepLines = Math.max(1, Math.min(lines.length, Math.trunc(configured)));
328	    if (keepLines >= lines.length) return null;
329	    const parsed = { mode: 'truncate', keepCount: keepLines, keepUnit: 'lines', targetSeq: event.seq, summary: '', fact: '' };
330	    const planResult = corePlan({ seq: event.seq, event }, parsed, toolName);
331	    if (planResult.rejected) return null;
332	
333	    const write = appendToolResultReplace(session, event.seq, planResult.content);
334	    if (!write.ok) return null;
335	    return {
336	      seq: event.seq,
337	      mode: planResult.mode,
338	      toolName,
339	      callId: resolveCallId(session, event),
340	      keepChars: planResult.keepChars,
341	      keepLines: planResult.keepLines ?? keepLines,
342	      before: planResult.before,
343	      after: planResult.after,
344	      trigger: 'auto'
345	    };
346	  } catch {
347	    return null;
348	  }
349	}
