39	/** Read the last assistant/message from a session snapshot. */
40	function lastAssistantMessage(session) {
41	  if (typeof session?.snapshotEvents === 'function') {
42	    const all = session.snapshotEvents();
43	    for (let i = all.length - 1; i >= 0; i -= 1) {
44	      const ev = all[i];
45	      if (ev.type === 'assistant/message') return { message: ev.data?.message, seq: ev.seq };
46	    }
47	    return null;
48	  }
49	  try {
50	    const msg = [...session.deriveMessages()].reverse().find((m) => m.role === 'assistant');
51	    return msg ? { message: msg, seq: undefined } : null;
52	  } catch {
53	    return null;
54	  }
55	}
