57	/** Persist one applyFromAssistantMessage result into the ledger. */
58	function recordResult(session, result) {
59	  if (!session?.id || !result) { diag('recordResult skip: id=' + (session && session.id) + ' hasResult=' + !!result); return; }
60	  const title = session.title || session.header?.title || '';
61	  for (const item of result.applied || []) {
62	    const summaryLen = item.fact ? item.fact.length : (item.summary ? item.summary.length : 0);
63	    const savedEntry = appendEvent(session.id, {
64	      sessionTitle: title,
65	      seq: item.seq,
66	      mode: item.mode,
67	      toolName: item.toolName || '',
68	      callId: item.callId || '',
69	      before: item.before,
70	      after: item.after,
71	      keepChars: item.keepChars || 0,
72	      keepLines: item.keepLines ?? null,
73	      fact: item.fact || '',
74	      summary: item.summary || '',
75	      summaryLen
76	    });
77	    diag('appendEvent session=' + session.id + ' seq=' + item.seq + ' -> ' + (savedEntry ? 'ok' : 'NULL'));
78	  }
79	  if (result.replySummary) {
80	    appendEvent(session.id, {
81	      sessionTitle: title,
82	      seq: result.replySummary.targetSeq,
83	      mode: 'reply',
84	      toolName: 'assistant_reply',
85	      before: result.replySummary.charsBefore ?? 0,
86	      after: result.replySummary.summary ? result.replySummary.summary.length : 0,
87	      summary: result.replySummary.summary || '',
88	      summaryLen: result.replySummary.summary ? result.replySummary.summary.length : 0
89	    });
90	  }
91	}
