93	/** Project historical assistant messages for the outgoing LLM request (dual-track + arg pruning). */
94	function projectOutgoing(messages, resolved) {
95	  if (!Array.isArray(messages)) return messages;
96	  return messages.map((msg) => {
97	    if (msg.role !== 'assistant') return msg;
98	    const content = msg.content;
99	    if (!Array.isArray(content)) return msg;
100	    const text = content.filter((b) => b.type === 'text').map((b) => b.text || '').join('\n');
101	    const hasReplyFence = resolved.replySummaryEnabled !== false && text.includes(REPLY_SUMMARY_OPEN_TAG);
102	    // Prune oversized tool-call arguments in history (keeps context lean, never throws).
103	    let pruned = msg;
104	    try {
105	      const prunedMsg = pruneToolCallArgs(msg, { maxCodeLen: 160, maxSpecLen: 160 });
106	      if (prunedMsg && prunedMsg !== msg) pruned = prunedMsg;
107	    } catch { /* keep original */ }
108	    return pruned;
109	  });
110	}
