112	export function apply(ctx, config = {}) {
113	  const resolved = liveConfig(config);
114	  if (!resolved.enabled) {
115	    ctx.logger?.info?.('[dsh-oswyn] disabled in configuration.');
116	    return;
117	  }
118	
119	  // ── 1. System prompt protocol section ──────────────────────────────────────
120	  ctx.effect?.(() => ctx.systemPrompt?.section?.({
121	    name: PROTOCOL_SECTION,
122	    order: 2500,
123	    text: () => protocolText()
124	  }), 'oswyn: protocol section');
125	
126	  // ── 2. Real-time distillation (AGENT-DRIVEN ONLY) ─────────────────────────
127	  // Tool output is NEVER auto-compressed: reading source files must stay resident.
128	  // OSWYN only nudges; the agent decides via fences.
129	  ctx.effect?.(() => ctx.on('session/event', (session, event) => {
130	    if (event?.type !== 'assistant/message' || event?.ignorable || !event?.data?.message) return;
131	    try {
132	      const result = applyFromAssistantMessage(session, event.data.message, event.seq, resolved);
133	      recordResult(session, result);
134	    } catch (err) {
135	      ctx.logger?.debug?.('[dsh-oswyn] event distillation skipped: ' + String(err).slice(0, 200));
136	    }
137	  }), 'oswyn: session-event distillation');
138	
139	  // ── 3. Step-boundary: distill the last landed assistant message + shape outgoing ──
